// <npm-compat-chart src="...">
//
// Renders the committed npm-package-compatibility summary
// (benchmarks/results/npm-compat.json, generated by
// scripts/generate-npm-compat-report.mjs) as a set of package cards: compile
// status, validation status, test pass rate (the package's own real test
// suite where one exists, otherwise a labeled differential-ops count — never
// conflated with each other), and a head-to-head perf comparison of the
// compiled Wasm export against the SAME pinned package running natively
// under Node. Same fetch-at-runtime convention as t262-charts.js /
// trend-chart.js / perf-benchmark-chart.js — no build-time templating.

class NpmCompatChart extends HTMLElement {
  static get observedAttributes() {
    return ["src"];
  }

  connectedCallback() {
    this.attachShadow({ mode: "open" });
    this._load();
  }

  attributeChangedCallback() {
    if (this.isConnected && this.shadowRoot) this._load();
  }

  async _load() {
    const src = this.getAttribute("src");
    if (!src) return;
    this._renderLoading();
    try {
      const res = await fetch(src);
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const data = await res.json();
      this._render(data);
    } catch (err) {
      this._renderError(err);
    }
  }

  _renderLoading() {
    this.shadowRoot.innerHTML = `${this._styles()}<div class="loading">Loading npm compatibility data…</div>`;
  }

  _renderError(err) {
    this.shadowRoot.innerHTML = `${this._styles()}<div class="loading error">Failed to load compatibility data: ${this._esc(String(err && err.message ? err.message : err))}</div>`;
  }

  _esc(s) {
    const div = document.createElement("div");
    div.textContent = s;
    return div.innerHTML;
  }

  _fmtUs(us) {
    if (us == null) return "—";
    if (us < 1) return `${(us * 1000).toFixed(0)}ns`;
    if (us < 1000) return `${us.toFixed(2)}µs`;
    return `${(us / 1000).toFixed(2)}ms`;
  }

  _statusBadge(ok, label) {
    const cls = ok === true ? "ok" : ok === false ? "bad" : "unknown";
    const text = ok === true ? "yes" : ok === false ? "no" : "—";
    return `<span class="badge ${cls}">${label}: ${text}</span>`;
  }

  _packageCard(pkg) {
    const compileOk = pkg.compile?.success ?? null;
    const validatesOk = pkg.validation?.validates ?? null;

    let testsHtml = `<div class="metric-row"><span class="metric-label">Tests</span><span class="metric-value muted">n/a — compile blocked</span></div>`;
    if (pkg.tests) {
      const { kind, passed, total, passRatePct } = pkg.tests;
      const pct = passRatePct != null ? passRatePct : total ? ((passed / total) * 100).toFixed(1) : null;
      const kindLabel = kind === "official-suite" ? "own test suite" : "differential ops (not the package's own tests)";
      testsHtml = `
        <div class="metric-row">
          <span class="metric-label">${this._esc(kindLabel)}</span>
          <span class="metric-value mono">${passed}/${total}${pct != null ? ` (${pct}%)` : ""}</span>
        </div>`;
    }

    let perfHtml = `<div class="metric-row"><span class="metric-label">Perf vs Node</span><span class="metric-value muted">not measured (surface red)</span></div>`;
    if (pkg.perf) {
      const { sampleOp, wasmUs, nodeUs, ratio } = pkg.perf;
      const faster = ratio >= 1 ? "wasm faster" : "node faster";
      const ratioLabel = ratio >= 1 ? `${ratio.toFixed(2)}×` : `${(1 / ratio).toFixed(2)}×`;
      perfHtml = `
        <div class="metric-row">
          <span class="metric-label">Perf vs Node</span>
          <span class="metric-value mono">${this._fmtUs(wasmUs)} (wasm) vs ${this._fmtUs(nodeUs)} (node) — <strong>${ratioLabel} ${faster}</strong></span>
        </div>
        <div class="metric-row sub"><span class="metric-label"></span><span class="metric-value muted">sample: ${this._esc(sampleOp)}</span></div>`;
    }

    const bugsHtml = (pkg.knownBugs ?? []).length
      ? `<div class="bugs">
          <div class="bugs-label">Known compiler bugs found via this package</div>
          <ul>
            ${pkg.knownBugs.map((b) => `<li><a href="https://github.com/loopdive/js2/issues/${b.issue}" target="_blank" rel="noopener">#${b.issue}</a> — ${this._esc(b.summary)}</li>`).join("")}
          </ul>
        </div>`
      : "";

    return `
      <div class="card">
        <div class="card-header">
          <h3>${this._esc(pkg.name)} <span class="version mono">v${this._esc(pkg.version)}</span></h3>
          <a class="entry-link" href="https://github.com/loopdive/js2/issues/${pkg.issue}" target="_blank" rel="noopener">#${pkg.issue}</a>
        </div>
        <div class="badges">
          ${this._statusBadge(compileOk, "Compiles")}
          ${this._statusBadge(validatesOk, "Validates")}
        </div>
        <div class="metrics">
          ${testsHtml}
          ${perfHtml}
        </div>
        ${bugsHtml}
        <div class="entry-file mono">${this._esc(pkg.entryFile)}</div>
      </div>`;
  }

  _render(data) {
    const packages = data.packages ?? [];
    const compiling = packages.filter((p) => p.compile?.success).length;
    const validating = packages.filter((p) => p.validation?.validates).length;

    this.shadowRoot.innerHTML = `
      ${this._styles()}
      <div class="summary-row">
        <div class="stat"><div class="stat-value">${packages.length}</div><div class="stat-label">packages tracked</div></div>
        <div class="stat"><div class="stat-value">${compiling}/${packages.length}</div><div class="stat-label">compile</div></div>
        <div class="stat"><div class="stat-value">${validating}/${packages.length}</div><div class="stat-label">validate</div></div>
      </div>
      <div class="cards">
        ${packages.map((p) => this._packageCard(p)).join("")}
      </div>
      ${data.note ? `<p class="note">${this._esc(data.note)}</p>` : ""}
      <p class="generated">Generated ${this._esc(data.generatedAt ?? "")}</p>
    `;
  }

  _styles() {
    return `
      <style>
        :host {
          display: block;
          font-family: var(--font, Inter, ui-sans-serif, system-ui, sans-serif);
          color: var(--fg, #fff);
        }
        .mono { font-family: var(--mono, "JetBrains Mono", "SF Mono", monospace); }
        .muted { color: var(--fg-faint, rgba(255,255,255,0.46)); }
        .loading { text-align: center; padding: 48px; color: var(--fg-faint, rgba(255,255,255,0.46)); }
        .loading.error { color: var(--fail, #f85149); }
        .summary-row {
          display: flex;
          gap: 16px;
          margin-bottom: 24px;
          flex-wrap: wrap;
        }
        .stat {
          background: var(--surface, rgba(255,255,255,0.05));
          border: 1px solid var(--border, rgba(255,255,255,0.12));
          padding: 16px 24px;
          min-width: 140px;
        }
        .stat-value { font-size: 28px; font-weight: bold; }
        .stat-label {
          color: var(--fg-faint, rgba(255,255,255,0.46));
          font-size: 12px;
          text-transform: uppercase;
          letter-spacing: 1px;
          margin-top: 4px;
        }
        .cards {
          display: grid;
          grid-template-columns: repeat(auto-fill, minmax(360px, 1fr));
          gap: 16px;
        }
        .card {
          background: var(--surface, rgba(255,255,255,0.05));
          border: 1px solid var(--border, rgba(255,255,255,0.12));
          padding: 20px;
        }
        .card-header {
          display: flex;
          align-items: baseline;
          justify-content: space-between;
          margin-bottom: 12px;
        }
        .card-header h3 {
          font-size: 18px;
          margin: 0;
          text-transform: capitalize;
        }
        .version {
          font-size: 12px;
          color: var(--fg-faint, rgba(255,255,255,0.46));
          font-weight: normal;
          margin-left: 6px;
        }
        .entry-link {
          font-size: 12px;
          color: var(--fg-faint, rgba(255,255,255,0.46));
          text-decoration: none;
        }
        .entry-link:hover { text-decoration: underline; }
        .badges { display: flex; gap: 8px; margin-bottom: 16px; flex-wrap: wrap; }
        .badge {
          font-size: 11px;
          text-transform: uppercase;
          letter-spacing: 0.5px;
          padding: 3px 8px;
          border: 1px solid currentColor;
        }
        .badge.ok { color: var(--pass, #3fb950); }
        .badge.bad { color: var(--fail, #f85149); }
        .badge.unknown { color: var(--fg-faint, rgba(255,255,255,0.46)); }
        .metrics { display: flex; flex-direction: column; gap: 6px; margin-bottom: 12px; }
        .metric-row {
          display: flex;
          justify-content: space-between;
          gap: 12px;
          font-size: 13px;
          border-bottom: 1px solid var(--border, rgba(255,255,255,0.12));
          padding-bottom: 6px;
        }
        .metric-row.sub {
          border-bottom: none;
          padding-top: 0;
          margin-top: -4px;
        }
        .metric-label {
          color: var(--fg-faint, rgba(255,255,255,0.46));
          text-transform: uppercase;
          font-size: 11px;
          letter-spacing: 0.5px;
          white-space: nowrap;
        }
        .metric-value { text-align: right; }
        .bugs {
          margin-top: 8px;
          padding-top: 12px;
          border-top: 1px solid var(--border, rgba(255,255,255,0.12));
        }
        .bugs-label {
          font-size: 11px;
          text-transform: uppercase;
          letter-spacing: 0.5px;
          color: var(--ce, #d29922);
          margin-bottom: 6px;
        }
        .bugs ul { margin: 0; padding-left: 18px; font-size: 12px; color: var(--fg-soft, rgba(255,255,255,0.68)); }
        .bugs li { margin-bottom: 4px; }
        .bugs a { color: inherit; }
        .entry-file {
          margin-top: 12px;
          font-size: 11px;
          color: var(--fg-faint, rgba(255,255,255,0.46));
        }
        .note {
          margin-top: 24px;
          font-size: 12px;
          color: var(--fg-faint, rgba(255,255,255,0.46));
          max-width: 800px;
        }
        .generated {
          margin-top: 8px;
          font-size: 11px;
          color: var(--fg-faint, rgba(255,255,255,0.46));
        }
      </style>
    `;
  }
}

customElements.define("npm-compat-chart", NpmCompatChart);
